-- Synthetic tests use column types only, with no production rows or credentials.
CREATE TABLE mis_internal.marketing_reconciliation_state (singleton boolean, revision bigint);
CREATE TABLE mis_internal.mis_gateway_batches (id bigint, parse_id uuid, actor_id uuid, accepted_at timestamp with time zone, authority text);
CREATE TABLE mis_internal.mis_gateway_jobs (id bigint, batch_id bigint, invoice_key text, status text, attempts integer, next_attempt_at timestamp with time zone, error_code text, import_id bigint, completed_at timestamp with time zone, result jsonb);
CREATE TABLE mis_internal.mis_gateway_publication (singleton boolean, target_batch_id bigint, published_batch_id bigint, stage text, snapshot_after text, last_result jsonb, updated_at timestamp with time zone, rules_version text, marketing_revision bigint, marketing_run_id bigint);
CREATE TABLE mis_internal.shadow_appointment_outcomes (appointment_id bigint, patient_id integer, appointment_date date, existing_booking_status text, matching_clinical_invoices integer, same_day_billing_invoices integer, duplicate_booking_count integer, evidence_outcome text, run_id bigint);
CREATE TABLE mis_internal.shadow_attribution_runs (id bigint, started_at timestamp with time zone, completed_at timestamp with time zone, status text, rule_version text, source_last_date date, invoice_count integer, patient_count integer, encounter_count integer, appointment_count integer, net_bill_total numeric(20,2), total_collected numeric(20,2), attributed_net_bill numeric(20,2), unattributed_net_bill numeric(20,2), count_no_source integer, count_late_source integer, count_unknown_source integer, integrity_passed boolean, findings jsonb, error_details text, refresh_step text);
CREATE TABLE mis_internal.shadow_encounters (encounter_key text, patient_id integer, care_setting text, episode_start date, episode_end date, doctor_key text, admission_id integer, invoice_count integer, clinical_invoice_count integer, clinical_verified boolean, net_bill numeric, total_collected numeric, run_id bigint);
CREATE TABLE mis_internal.shadow_invoice_attribution (invoice_id bigint, patient_id integer, invoice_date date, encounter_key text, attributed_source text, attribution_class text, net_bill numeric, total_collected numeric, run_id bigint);
CREATE TABLE mis_internal.shadow_invoice_evidence (invoice_id bigint, patient_id integer, invoice_date date, clinical_line_evidence boolean, clinical_line_count integer, encounter_key text, run_id bigint);
CREATE TABLE mis_internal.shadow_patient_acquisitions (patient_id integer, first_recorded_invoice_date date, first_clinical_invoice_date date, source text, source_event_date date, evidence_table text, evidence_id text, evidence_authentication text, attribution_class text, historical_window_start date, notes text, run_id bigint);

